      "id": "D11", "contract": "Raffle", "function": "releaseProtocolFees", "group_bug_class": "usdc-blacklist-immutable-recipient",
      "members": ["R35"], "synonym_merge": null, "judge_stage": "withdraw",
      "mechanisms": [
        {"id": "M1", "members": ["R35"], "summary": "protocolTreasury is a factory immutable (F:39) shared by every clone. A USDC blacklisting of the treasury permanently freezes the 5% fee of every raffle (:385-390). Sibling sites are sponsorRecipient (:375-380) and releaseSponsorPrize (:404) for collections that blocklist recipients."}
      ],
      "mitigations": [],
      "cautions": [],
      "gates": {
        "G1": ["ALLOWS", "protocolTreasury is immutable, and there is no redirect path."],
        "G2": ["BLOCKS", "Requires Circle to blacklist the treasury; there is no attacker path."],
        "G3": ["BLOCKS", "Only the protocol treasury loses."],
        "G4": ["ALLOWS", "The fees would be stuck factory-wide."]
      },
      "promotion": "Not promoted: [lenses: 1], and there is no attacker path (G2/G3 BLOCK).",
      "decision": "LEAD", "severity": null, "severity_reason": null, "report_id": "Lead-5"
    },
    {
      "id": "D12", "contract": "Raffle", "function": "releaseSponsorPrize", "group_bug_class": "missing-payout-time-destination-screen",
      "members": ["R02", "R14", "R18", "R33", "R40"],
      "synonym_merge": "missing-payout-destination-screen (R02), codeless-destination-screen-bypass (R14), config-time-only-destination-screen (R18), missing-payout-time-destination-screen (R33), payout-screen-inconsistency (R40): all say the NFT return is not re-screened at payout, and a counterfactual clone address passes the init-time screen",
      "judge_stage": "withdraw",
      "mechanisms": [
        {"id": "M1", "members": ["R02", "R14", "R18", "R33", "R40"], "summary": "The sponsor sets sponsorRecipient to a predictable, not-yet-deployed factory CREATE clone address. It passes F:163-169 (the isRaffle mapping) and initialize (:193-195; the registry check is skipped for code-less addresses at :602). Once that clone exists, releaseSponsorPrize (:402-405) moves the NFT into it, against DESIGN.md's 'Never move assets between raffle clones', and the USDC sibling reverts at :565."},
        {"id": "S1", "members": ["R18", "R33"], "summary": "Sibling. The code-less gap in _update (:498 -> :602) lets a ticket be sent to a future clone address (self-harm)."}
      ],
      "mitigations": [
        {"option": "A", "kind": "validate", "raw_id": "R02", "quote": "Minimal mitigation: in releaseSponsorPrize, revert if _isProtocolDestination(recipient, address(prizeToken)), mirroring _transferQuote."},
        {"option": "A", "kind": "validate (same change)", "raw_id": "R40", "quote": "Adding the same `_isProtocolDestination` check before Raffle.sol:404 would make the two payout paths consistent."}
      ],
      "cautions": [
        {"raw_id": "R18", "quote": "but because sponsorRecipient is immutable the prize would still be stranded rather than moved."}
      ],
      "gates": {
        "G1": ["ALLOWS", ":402-405 makes no payout-time _isProtocolDestination check. The init-time screen skips the registry for code-less addresses (:602), and F:166 only sees clones that are already registered."],
        "G2": ["ALLOWS", "Reachable only by the sponsor deliberately choosing a future clone CREATE address as sponsorRecipient."],
        "G3": ["BLOCKS", "Self-harm only: the sponsor who chose the address is the only party that loses, and the receiving clone's accounting is unaffected."],
        "G4": ["ALLOWS", "The NFT is permanently stranded in another clone."]
      },
      "promotion": "Demoted: [lenses: 5], but G3 BLOCKS (self-harm only, excluded from findings by the shared rules). Kept as a surviving LEAD.",
      "decision": "LEAD", "severity": null, "severity_reason": null, "report_id": "Lead-6"
    },
    {
      "id": "D13", "contract": "Raffle", "function": "_update", "group_bug_class": "ticket-transfer-during-pending-vrf",
      "members": ["R03", "R06", "R09", "R12", "R22", "R29", "R31"],
      "synonym_merge": "outcome-frontrun-ticket-transfer (R03), post-request-ticket-transfer (R06), vrf-outcome-frontrun-ticket-trade (R09), informed-ticket-trading-during-draw (R12), vrf-reveal-ticket-sniping (R22), vrf-input-after-request (R29), transfer-during-pending-randomness (R31): all say tickets stay transferable while the VRF outcome can already be derived",
      "judge_stage": "withdraw (ticket transfer)",
      "mechanisms": [
        {"id": "M1", "members": ["R03", "R06", "R09", "R12", "R22", "R29", "R31"], "summary": "Pre-inclusion front-run. winningEntry = word % totalEntries + 1 (:518) follows from the pending fulfillment. A watcher fills a stale listing of the winning ticket, or dumps losing tickets into standing bids, before the result is on-chain."},
        {"id": "M2", "members": ["R09", "R22", "R29", "R31"], "summary": "Same-block bundle or back-run around resolution, which a Drawing-only lock does not stop."},
        {"id": "M3", "members": ["R22"], "summary": "Aggravating factor. Tickets have no tokenURI, and every clone returns the same name()/symbol() (:479-487), so listings cannot show a ticket's range or raffle state."}
      ],
      "mitigations": [
        {"option": "A", "kind": "restrict (Drawing-only lock)", "raw_id": "R03", "quote": "Possible mitigation: block ticket transfers while status == Drawing."},
        {"option": "A", "kind": "restrict (Drawing-only lock, same change)", "raw_id": "R29", "quote": "The smallest change would be for _update to reject ticket transfers that are neither mints nor burns while status == Drawing, but that removes only the pre-resolution window."},
        {"option": "B", "kind": "restrict (lock through the resolution block)", "raw_id": "R22", "quote": "block transfers other than mint and burn from requestDraw until block.timestamp > resolvedAt, and document that holders must cancel orders before the draw."},
        {"option": "C", "kind": "restrict (operator-initiated transfers from requestDraw onward)", "raw_id": "R09", "quote": "The only robust fix, blocking operator-initiated transfers from requestDraw onward, conflicts with the documented bearer-claim design."}
      ],
      "cautions": [
        {"raw_id": "R31", "quote": "Blocking transfers only during Drawing would also not protect listings left open after resolution."}
      ],
      "gates": {
        "G1": ["ALLOWS", "_update (:497-502) screens destinations but never status, so tickets move freely in Drawing and in the resolution block."],
        "G2": ["UNCERTAIN", "Needs pre-inclusion visibility of the VRF fulfillment (not verified offline) plus a stale open order on a secondary market."],
        "G3": ["ALLOWS", "Victims are counterparties with open sell listings or bids (third parties)."],
        "G4": ["UNCERTAIN", "Real value moves (R22: seller under-paid 16,500 USDC), but this is close to standard MEV on user-chosen open orders."]
      },
      "promotion": "Promoted: [lenses: 7]; no code path interrupts the path.",
      "decision": "FINDING", "severity": "Low",
      "severity_reason": "Highly constrained (needs a stale order and a fulfillment visible before inclusion), with protocol accounting unaffected and bearer transferability documented (:491). Torn with Medium, chose the lower.",
      "report_id": "L-1"
    },
    {
      "id": "D14", "contract": "Raffle", "function": "fulfillRandomWords", "group_bug_class": "sponsor-reserve-flip",
      "members": ["R08", "R13", "R20", "R38"],
      "synonym_merge": "sponsor-reserve-flip (R08), reserve-flip-by-sponsor-top-up (R13), reserve-threshold-self-funding (R20), reserve-threshold-manipulation (R38): all are a sponsor top-up of the shortfall that flips the outcome predicate at :521",
      "judge_stage": "cross-chain receive (async VRF callback analogue)",
      "mechanisms": [
        {"id": "M1", "members": ["R08", "R13", "R20", "R38"], "summary": "The outcome predicate totalEntries >= reserveEntries (:521) counts sponsor-funded entries, 95% of which come back under NftWon (:544). The sponsor fills the shortfall at endTime-1 and turns buyers' CashWon (80% cash) into an NftWon over-priced NFT. R08: buyers -270, sponsor +265, treasury +5. R20: buyers -2,400, sponsor +2,300, treasury +100."}
      ],
      "mitigations": [
        {"option": "-", "kind": "none-on-chain", "raw_id": "R08", "quote": "There is no sybil-proof code fix: the sale cap proposed for the dilution FINDING does not close this gap."},
        {"option": "-", "kind": "none-on-chain", "raw_id": "R38", "quote": "No address-based check can stop Sybil self-purchase."}
      ],
      "cautions": [
        {"raw_id": "R13", "quote": "This is probably accepted design and is reported only for calibration."}
      ],
      "gates": {
        "G1": ["ALLOWS", ":521 compares totalEntries, which includes sponsor-funded entries, with reserveEntries; nothing excludes them."],
        "G2": ["ALLOWS", "The sponsor buys the shortfall at endTime-1, and 95% of it comes back under NftWon."],
        "G3": ["ALLOWS", "Victims are the under-reserve buyers."],
        "G4": ["UNCERTAIN", "Expected value moves only when the NFT is worth less than about 0.8x the pot (R08 example above)."]
      },
      "promotion": "Promoted: [lenses: 4]; no code path interrupts the path.",
      "decision": "FINDING", "severity": "Low",
      "severity_reason": "Same as D03: torn between Medium and Low, and chose Low because the flip only pays for an over-priced reserve and CashWon is not a buyer entitlement.",
      "report_id": "L-2"
    },
    {
      "id": "D15", "contract": "Raffle", "function": "fulfillRandomWords", "group_bug_class": "vrf-result-preview-ticket-sniping",
      "members": ["R17"], "synonym_merge": null, "judge_stage": "cross-chain receive (async VRF callback analogue)",
      "mechanisms": [
        {"id": "M1", "members": ["R17"], "summary": "The result is a pure function of the single VRF word (:518-521), and ticket ranges are public (:451-455). A watcher who sees the oracle's fulfillment transaction before RaffleResolved is mined can trade against resting orders."}
      ],
      "mitigations": [
        {"option": "A", "kind": "restrict (Drawing-only lock)", "raw_id": "R17", "quote": "Blocking ticket transfers while `status == Drawing` would close only the pre-inclusion window and conflicts with the bearer-claim design."}
      ],
      "cautions": [],
      "gates": {
        "G1": ["ALLOWS", "The outcome at :518 is deterministic, and transfers are open (:497-502)."],
        "G2": ["UNCERTAIN", "Mempool visibility and the coordinator's delivery semantics are not verified (wrapper and coordinator are not vendored)."],
        "G3": ["ALLOWS", "Victims are holders with resting orders."],
        "G4": ["UNCERTAIN", "Close to generic stale-order NFT MEV."]
      },
      "promotion": "Not promoted: [lenses: 1], and the external path is unverified. Same mechanism as L-1 (Raffle::_update), kept separate by function isolation.",
      "decision": "LEAD", "severity": null, "severity_reason": null, "report_id": "Lead-7"
    }
  ],
  "chains": [
    {"chain": ["L-2", "M-1"], "also": ["L-3"], "summary": "The sponsor tops up the reserve shortfall for about 5% of its cost to force NftWon (L-2/L-3), then blocks delivery of a sponsor-administered prize (M-1). It collects 95% of the buyers' pot while the winner receives nothing. Combined, this is worse than either alone: M-1 alone needs organic demand >= reserve, and the flip alone still leaves buyers a chance at the NFT. It is not reported as a separate finding because one untrusted actor (the sponsor) controls both legs, and the only trust boundary crossed is M-1's prize-contract boundary."}
  ]
}

toolu_01MUaZEswSBp2dfcWfqDYJPs.content:
{
  "_about": "Orchestrator Turn 6 judgement data (attempt-02, public-evidence variant). Groups are ordered in the native judge order: constructor/initialize -> setters -> deposit -> accrue -> borrow -> liquidate -> withdraw -> cross-chain receive (mapped: createRaffle -> (no setters) -> buyEntries -> requestDraw/_settleWinningTicket -> (no borrow) -> enableRefunds forced exit -> redeem/release/_update -> fulfillRandomWords async callback). Gates: G1 code path stops it? G2 preconditions reachable? G3 harm to someone other than the attacker? G4 real value? UNCERTAIN counts as ALLOWS. Gates are evaluated for every group; for LEAD groups they drive promotion/demotion.",
  "groups": [
    {
      "id": "D01", "contract": "RaffleFactory", "function": "createRaffle", "group_bug_class": "spoofable-escrow-verification",
      "members": ["R39"], "synonym_merge": null, "judge_stage": "constructor/initialize",
      "mechanisms": [
        {"id": "M1", "members": ["R39"], "summary": "A hostile prize contract can call Raffle.onERC721Received itself during its own safeTransferFrom (F:128) and answer the factory ownerOf/status checks (F:129-134), producing an Active raffle with nothing escrowed; the same contract answers the delivery checks (Raffle.sol:335, :405)."}
      ],
      "mitigations": [
        {"option": "A", "kind": "document", "raw_id": "R39", "quote": "The recommendation is to document the prize trust boundary for buyers, not to change code."}
      ],
      "cautions": [],
      "gates": {
        "G1": ["ALLOWS", "F:129/F:132 and Raffle.sol:421-426 verify escrow only through calls and answers of the prize contract itself, so a hostile prize can forge onERC721Received and ownerOf."],
        "G2": ["ALLOWS", "Any sponsor can deploy a hostile ERC-165 contract at zero cost; F:155-177 checks only code presence, protocol plumbing and supportsInterface."],
        "G3": ["UNCERTAIN", "Buyers of that raffle are not the sponsor, but they opted into an unvetted prize contract; the harm equals entering a raffle for a worthless prize."],
        "G4": ["BLOCKS", "No incremental loss is established beyond the buyer-visible worthless-prize risk, and no check that only queries the prize contract can remove it."]
      },
      "promotion": "Not promoted: [lenses: 1], and the full loss path beyond worthless-prize equivalence does not exist in source (G4 BLOCKS).",
      "decision": "LEAD", "severity": null, "severity_reason": null, "report_id": "Lead-1"
    },
    {
      "id": "D02", "contract": "Raffle", "function": "buyEntries", "group_bug_class": "sponsor-rebated-late-dilution",
      "members": ["R07"], "synonym_merge": null, "judge_stage": "deposit",
      "mechanisms": [
        {"id": "M1", "members": ["R07"], "summary": "After the reserve is met, the sponsor buys entries from a fresh address in the last block before endTime. NftWon pays 95% of the gross pot, including those entries, back to sponsorRecipient (Raffle.sol:544, :554), so each sponsor entry costs 5% net but carries full weight in the draw (Raffle.sol:518). Earlier buyers cannot exit: refunds open only at endTime+2d (:286-287), and the draw opens at endTime (:242)."}
      ],
      "mitigations": [
        {"option": "A", "kind": "restrict", "raw_id": "R07", "quote": "Stop the sale at the reserve in buyEntries (`if (lastEntry > reserveEntries) revert ...`), so no sponsor-rebated entries can be minted after organic demand meets the reserve."}
      ],
      "cautions": [
        {"raw_id": "R07", "quote": "A sponsor fill of the gap below the reserve remains possible; it is tracked as a separate lead."}
      ],
      "gates": {
        "G1": ["ALLOWS", "buyEntries (:215-221) checks only status, sale time, recipient, count and overflow; it has no cap once the reserve is met and no exclusion of sponsor-controlled buyers. _update (:497-502) screens only protocol plumbing."],
        "G2": ["ALLOWS", "Sponsor capital is locked only from endTime-1 until settle plus release (minutes to hours), and 95% comes back in NftWon. It is not flash-loanable, but the attack pays whenever NFT value > 5% of the final pot; sybil purchases cannot be told apart from real ones."],
        "G3": ["ALLOWS", "Victims are the organic ticket holders who bought before the sale closed: their odds of winning the NFT are diluted while their USDC goes to sponsorRecipient and the treasury."],
        "G4": ["ALLOWS", "Expected value moves between cohorts. R07 example: Alice -9,000 USDC EV, sponsor +4,500, treasury +4,500."]
      },
      "promotion": "Raw FINDING; all gates ALLOWS.",
      "decision": "FINDING", "severity": "Medium",
      "severity_reason": "The loss is a probabilistic transfer of expected value between cohorts with no insolvency. I was torn with High because the sponsor creates every precondition, and chose the lower.",
      "report_id": "M-2"
    },
    {
      "id": "D03", "contract": "Raffle", "function": "buyEntries", "group_bug_class": "reserve-self-dealing",
      "members": ["R28", "R32"], "synonym_merge": "reserve-self-dealing (R28) == sponsor-self-dealing-reserve (R32): both are a sponsor top-up of the reserve shortfall that flips CashWon to NftWon", "judge_stage": "deposit",
      "mechanisms": [
        {"id": "M1", "members": ["R28", "R32"], "summary": "When organic demand is below the reserve, the sponsor buys the shortfall just before endTime. totalEntries >= reserveEntries (Raffle.sol:521) then selects NftWon, which rebates 95% of the sponsor's own purchase (:544) and replaces the buyers' 80% cash outcome with a chance at an NFT worth less."}
      ],
      "mitigations": [
        {"option": "-", "kind": "none-on-chain", "raw_id": "R28", "quote": "Addresses the sponsor controls cannot be identified on-chain, so any fix is at the design level."},
        {"option": "-", "kind": "none-on-chain", "raw_id": "R32", "quote": "Sybil addresses make a msg.sender != sponsor check useless, so there is no minimal on-chain fix."}
      ],
      "cautions": [],
      "gates": {
        "G1": ["ALLOWS", "Nothing in buyEntries (:209-237) excludes sponsor-funded entries from the reserve test at :521."],
        "G2": ["ALLOWS", "The sponsor buys the shortfall just before endTime, and 95% of it comes back under NftWon."],
        "G3": ["ALLOWS", "Victims are under-reserve organic buyers, whose CashWon expected value (80% of the pot) is replaced by a smaller chance at the NFT."],
        "G4": ["UNCERTAIN", "The expected-value transfer is real only when the NFT is worth less than about 0.8x the pot, and buyers were never guaranteed CashWon: any third party crossing the reserve gives the same outcome."]
      },
      "promotion": "Promoted: [lenses: 2]; no code path interrupts the path.",
      "decision": "FINDING", "severity": "Low",
      "severity_reason": "Torn between Medium and Low; chose Low because the flip only pays for an over-priced reserve and CashWon is not a buyer entitlement. No sybil-resistant code fix exists.",
      "report_id": "L-3"
    },
    {
      "id": "D04", "contract": "Raffle", "function": "requestDraw", "group_bug_class": "immutable-vrf-wrapper-dependency",
      "members": ["R26", "R36"], "synonym_merge": "external-dependency-dos (R26) == immutable-vrf-wrapper-dependency (R36): both describe the immutable Chainlink wrapper with no migration path", "judge_stage": "accrue (draw request)",
      "mechanisms": [
        {"id": "M1", "members": ["R26", "R36"], "summary": "Wrapper disabled or deprecated: getVrfRequestPrice/requestRandomnessPayInNative (Raffle.sol:249, :257) revert for every raffle of the factory, so every sold raffle can only end in Refunding after endTime+2d."},
        {"id": "M2", "members": ["R26", "R36"], "summary": "Wrapper unfunded, or coordinator re-pointed while a request is pending: a paid request is never fulfilled, so the requester's native fee is lost and refunds open at drawRequestedAt+2d."}
      ],
      "mitigations": [],
      "cautions": [
        {"raw_id": "R26", "quote": "DESIGN.md treats the wrapper as a trusted canonical dependency and rules out mutable configuration, so this is probably accepted design."}
      ],
      "gates": {
        "G1": ["BLOCKS", "enableRefunds (:286-291) guarantees 100% refunds after endTime+2d or drawRequestedAt+2d, so no principal can be lost. Only time and the requester's own fee remain at risk."],
        "G2": ["BLOCKS", "The trigger is Chainlink, a trusted canonical dependency under DESIGN.md, disabling or migrating the wrapper; no attacker can create it."],
        "G3": ["UNCERTAIN", "Buyers and sponsors are delayed. The fee loss falls on whoever chose to request the draw."],
        "G4": ["BLOCKS", "Funds are locked only for a bounded time and then refunded in full; nothing is lost."]
      },
      "promotion": "Demoted: [lenses: 2] does not override a code path (the refund deadlines, G1 BLOCKS) that interrupts loss before harm. Kept as a surviving LEAD.",
      "decision": "LEAD", "severity": null, "severity_reason": null, "report_id": "Lead-2"
    },
    {
      "id": "D05", "contract": "Raffle", "function": "_settleWinningTicket", "group_bug_class": "sponsor-self-entry-rebate",
      "members": ["R04", "R21", "R42"], "synonym_merge": "sponsor-self-entry-rebate (R04, R42 exact group_key match) + sponsor-self-purchase-rebate (R21 synonym)", "judge_stage": "accrue (settlement)",
      "mechanisms": [
        {"id": "M1", "members": ["R04", "R21", "R42"], "summary": "(A) Dilution under NftWon. :544 pays the sponsor 95% of the gross pot, including entries it bought itself, so last-block sponsor entries dilute buyers' odds on the fixed-value NFT at 5% net cost. R04 A: buyers -500, sponsor +450. R21 (a): buyers -9,000, sponsor +4,500."},
        {"id": "M2", "members": ["R04", "R21"], "summary": "(B) Reserve flip. A sponsor top-up of the shortfall turns CashWon into NftWon. R04 B: buyers -150, sponsor +125. R21 (b): buyers -2,500, sponsor +2,250."}
      ],
      "mitigations": [
        {"option": "A", "kind": "restrict (cap)", "raw_id": "R04", "quote": "Partial fix: cap sponsorProceeds at reserveEntries×ENTRY_PRICE×95% and send the surplus to the winner/cash pool. That removes variant A; variant B would still need disclosure."},
        {"option": "A", "kind": "restrict (cap) - same operation, constant without the 95% factor", "raw_id": "R21", "quote": "A design change such as capping the NftWon sponsor share at reserveEntries*ENTRY_PRICE, with the excess paid to the winner, fixes (a) but not (b)."}
      ],
      "cautions": [
        {"raw_id": "R42", "quote": "Excluding addresses is defeated by Sybil addresses, so there is no one-line mitigation."}
      ],
      "gates": {
        "G1": ["ALLOWS", ":544 computes the NftWon sponsor share over the gross pot, with no exclusion or cap for sponsor-funded entries."],
        "G2": ["ALLOWS", "Same as D02: the sponsor's capital is short-lived and 95% of it is rebated."],
        "G3": ["ALLOWS", "Victims are the organic buyers (variant A) and the under-reserve buyers (variant B)."],
        "G4": ["ALLOWS", "Expected value moves between cohorts (variant A examples above)."]
      },
      "promotion": "Promoted: [lenses: 3], and the full path with numbers exists in source.",
      "decision": "FINDING", "severity": "Medium",
      "severity_reason": "Same as D02 (variant A drives the severity). Torn with High and chose the lower because the loss is a transfer of expected value.",
      "report_id": "M-3"
    },
    {
      "id": "D06", "contract": "Raffle", "function": "_settleWinningTicket", "group_bug_class": "nftwon-split-without-delivery",
      "members": ["R01", "R41"], "synonym_merge": "sponsor-paid-before-prize-delivery (R01) == missing-fallback-undeliverable-prize (R41): both say the NftWon split is booked with no dependency on, or fallback for, NFT delivery", "judge_stage": "accrue (settlement)",
      "mechanisms": [
        {"id": "M1", "members": ["R01", "R41"], "summary": "The NftWon branch books 95%/5% to sponsorRecipient and the treasury (:543-555), payable at once through the release functions (:375-392). The NFT's only exit is redeem (:334-337). NftWon cannot reach Refunding (:292-293), and releaseSponsorPrize is barred (:397). A sponsor-administered upgradeable prize that blocks transfers from the clone after settlement strands the winner (R01/R41: 5,000 USDC pot, 4,750 + 250 released)."}
      ],
      "mitigations": [
        {"option": "A", "kind": "validate", "raw_id": "R01", "quote": "Minimal mitigation if in scope: in releaseSponsorProceeds, require prizeClaimed when status == NftWon."}
      ],
      "cautions": [
        {"raw_id": "R01", "quote": "Trade-off: a winner who never redeems then also defers the sponsor's proceeds."},
        {"raw_id": "R41", "quote": "Any delivery gate must still handle a winner who never redeems, because there is no redemption deadline."}
      ],
      "gates": {
        "G1": ["ALLOWS", "The NftWon split (:543-555) has no delivery dependency. Both release functions (:375-392) check only amount != 0, NftWon has no route to Refunding (:292-293), and releaseSponsorPrize excludes NftWon (:397-398)."],
        "G2": ["ALLOWS", "A sponsor-administered upgradeable or pausable collection passes F:154-179 and the escrow checks at F:128-134, and DESIGN.md calls prize contracts untrusted."],
        "G3": ["ALLOWS", "The victim is the winning-ticket holder (buyer cohort)."],
        "G4": ["ALLOWS", "The prize can never be delivered after 100% of the pot is paid out."]
      },
      "promotion": "Promoted: [lenses: 2], and the full path exists in source (R01 steps 1-7).",
      "decision": "FINDING", "severity": "Medium",
      "severity_reason": "Same family and reasoning as M-1: it needs a prize whose transfers an admin can gate (an external condition). Reported separately because function isolation never merges across functions.",
      "report_id": "M-4"
    },
    {
      "id": "D07", "contract": "Raffle", "function": "enableRefunds", "group_bug_class": "empty-raffle-cancel-griefing",
      "members": ["R15", "R23", "R27"], "synonym_merge": "empty-raffle-cancel-griefing (R15) == frontrun-cancel-grief (R23) == griefing-cancel-block (R27)", "judge_stage": "liquidate (forced-exit analogue)",
      "mechanisms": [
        {"id": "M1", "members": ["R15", "R23", "R27"], "summary": "A 1-entry buyEntries front-runs the sponsor's empty-raffle cancel (Raffle.sol:280-284), forcing the sold-raffle deadline endTime+2d (:286-287). The griefer's 1 USDC is refundable or returns 80% (0.8 USDC) under CashWon."},
